"""Static authoring: build portfolio pages from audited existing content."""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parent.parent
def head(name):
    source = (ROOT / 'originals' / name).read_text(encoding='utf-8')
    h = source.split('</head>')[0]
    h = re.sub(r'<base[^>]*>', '', h)
    h = re.sub(r'<link[^>]+(?:fonts\.google|fonts\.gstatic)[^>]*>', '', h)
    h = re.sub(r'<link[^>]+href="(?:\.\./)?css/[^>]*>', '', h)
    h = re.sub(r'<style>.*?</style>', '', h, flags=re.S)
    h = h.replace('content="noindex"', 'content="index, follow"')
    return h + '\n<link rel="stylesheet" href="css/folio.css">\n<link rel="stylesheet" href="css/editorial.css">\n<link rel="preload" as="font" type="font/woff2" href="fonts/ibm-plex-sans.woff2" crossorigin>\n</head>'

