def discovery(compact=False):
    rows=''
    for i,(name,category,desc,icon,detail) in enumerate(programs[:3] if compact else programs):
        rows+=f'''<details class="program-tile" data-program data-category="{category}" data-name="{name.lower()}"><summary><img src="images/{icon}" width="48" height="48" alt=""><span><small>{category}</small><strong>{name}</strong></span><span class="tile-arrow" aria-hidden="true">↗</span></summary><p>{desc}</p><div class="program-detail"><p>{detail}</p><span class="sample-label">Discovery preview · original program mechanics</span></div></details>'''
    search='' if compact else '''<div class="discovery-controls"><label class="search-field"><span>Search programs</span><input type="search" data-program-search placeholder="Try Boost Rank" autocomplete="off"></label><label class="category-field"><span>Category</span><select data-program-category><option value="all">All categories</option>'''+''.join(f'<option>{p[1]}</option>' for p in programs)+'''</select></label></div><p class="search-count" aria-live="polite" data-program-count>8 programs</p>'''
    return f'''<div class="discovery-ui" {'data-discovery' if not compact else ''}><div class="app-bar"><span class="app-mark" aria-hidden="true">a<span>●</span></span><span>Partner growth</span><span class="app-account">Maison Solara <span aria-hidden="true">⌄</span></span></div><div class="app-layout"><aside class="app-side" aria-label="Workflow context"><span>Property</span><span>Reservations</span><span>Calendar</span><strong>Growth programs</strong><span>Payout</span></aside><div class="app-content"><p class="app-eyebrow">GROW YOUR PROPERTY</p><h{'3' if compact else '2'}>Find your next<br>growth opportunity.</h{'3' if compact else '2'}><p class="app-intro">The right program. A clearer next step.</p>{search}<div class="program-grid">{rows}</div>{'<a class="app-link" href="partner-growth-programs.html#concept">Explore all programs <span aria-hidden="true">→</span></a>' if compact else '<p class="sample-label">Updated concept · Shopify-inspired discovery. Expand a program to review its existing mechanics. No account changes.</p>'}</div></div></div>'''

def evidence(kind):
    if kind=='growth':
        title='One hub. A shared design language.'
        metrics=[('$521M+','2025 program portfolio revenue'),('12%','Activating a program within 24 hours'),('4 / 7','Co-owned tenets / lifecycle patterns')]
        text='The portfolio revenue predates the MVP launched in Q1 2026. It describes the programs’ business scale, not revenue caused by the hub redesign. The original source does not provide a baseline or sample size for the activation figure.'
        detail='''<details><summary>Scope, research &amp; program-level evidence</summary><p>8 programs · 3 design tracks · 5+ business owners. Tested with 8 partners across 3 markets. MVP shipped in one quarter; A/B test December 2025–January 2026.</p><div class="evidence-table-wrap"><table><caption>Program estimates as reported in the original case study</caption><thead><tr><th>Program</th><th>Evidence &amp; context</th></tr></thead><tbody><tr><td>Promotions</td><td>$233M estimated revenue. Mega Sale: 755M+ impressions; Seasonal: $89.7M; Always-on: $29M; Targeted: $114.2M, 72% penetration.</td></tr><tr><td>Agoda Growth Program</td><td>$131M estimated revenue; +10% average booking uplift; 1.8× more PPC/MSE ad spend.</td></tr><tr><td>Agoda Advanced</td><td>$120M estimated revenue.</td></tr><tr><td>Maximum Gain</td><td>$75M estimated revenue; 10,000+ affiliates. Previous UI example used $54M; the program description uses $75M.</td></tr><tr><td>Boost Rank</td><td>$67M estimated revenue.</td></tr><tr><td>Sponsored Listing</td><td>$17M estimated revenue.</td></tr><tr><td>Dynamic Rates</td><td>$7.5M estimated revenue.</td></tr><tr><td>Flagship Store</td><td>30× average ROAS; +29% net room nights; +32% revenue; 160k+ daily impressions, reported for live partners.</td></tr></tbody></table></div><p>Program estimates have unspecified periods and may overlap. They are not added together or reconciled to the 2025 portfolio total. Sample property balances and predicted uplift in the original mockup are illustrative UI data, not outcomes.</p></details>'''
    elif kind=='discount':
        title='A clearer rate. Fewer complaints.'
        metrics=[('10–12%','Activation lift · original project index'),('−3%','Partner-support handle time'),('#1','Complaint category reported eliminated'),('1.5 yrs','Ongoing impact reported in source')]
        text='These are reported outcomes from the existing portfolio, not measured results of this updated concept. The source narrative calls the complaint #1; its before/after chart says “Top 3.” That ranking remains unresolved.'
        detail='''<details><summary>Research &amp; attribution context</summary><p>Tested stacking explanations with 12 partners. Workshops involved 5+ business owners. Team: 1 Product Owner, 8 Developers and 1 UX Researcher. Shipped behind feature flags; tracked handle time, activation and complaint volume. The source gives no experiment sample sizes, confidence intervals or activation baseline.</p></details>'''
    else:
        title='From working days to minutes.'
        metrics=[('6m 8s','Average service creation · formerly 1–2 days'),('68.8','Final System Usability Scale score'),('4.4/5','Reported deployment ease')]
        text='Reported outcomes across three quarters. The original results card rounds creation time to “6 Min”; the narrative gives 6m 8s. No new measurements are attributed to the updated concept.'
        detail='''<details><summary>Research, team &amp; SUS progression</summary><p>15+ developer interviews · 47 usability issues documented. Team: 1 Product Owner, 4–5 Engineers and 1 Frontend Engineer.</p><p class="sus-line">22Q4: 61.9 → 23Q2: 63.4 → 23Q4: 68.8</p><p>The existing study cites industry-average SUS of 68 and a future goal of 70+. That goal is not presented as an achieved result. The source does not provide participant counts for SUS or the deployment-ease rating.</p></details>'''
    return f'''<section class="evidence-card evidence--{kind}" aria-labelledby="evidence-title"><p class="eyebrow">Evidence &amp; outcomes · reported in original portfolio</p><h2 id="evidence-title">{title}</h2><dl class="evidence-metrics">{''.join(f'<div><dt>{label}</dt><dd>{num}</dd></div>' for num,label in metrics)}</dl><p class="evidence-context">{text}</p>{detail}</section>'''

